s = input()
vowels = 0
consonants = 0
for ch in s:
    if ch.isalpha():
        if ch.lower() in "aeiou":
            vowels += 1
        else:
            consonants += 1
print(f"Vowels: {vowels}, Consonants: {consonants}")

s = input()
count = 0
in_word = False
for ch in s:
    if not ch.isspace():
        if not in_word:
            count += 1
            in_word = True
    else:
        in_word = False
print(count)

s = input()
out = []
for ch in s:
    if "A" <= ch <= "Z":
        out.append(chr(ord(ch) + 32))
    elif "a" <= ch <= "z":
        out.append(chr(ord(ch) - 32))
    else:
        out.append(ch)
print("".join(out))

