s = input()
freq = {}
for ch in s:
    if not ch.isspace():
        freq[ch] = freq.get(ch, 0) + 1
if not freq:
    print("None")
else:
    best_ch = ""
    best_cnt = 0
    for ch, cnt in freq.items():
        if cnt > best_cnt:
            best_cnt = cnt
            best_ch = ch
    print(f"{best_ch} {best_cnt}")

s1 = input()
s2 = input()
counts = {}
for ch in s1:
    if not ch.isspace():
        c = ch.lower()
        counts[c] = counts.get(c, 0) + 1
for ch in s2:
    if not ch.isspace():
        c = ch.lower()
        counts[c] = counts.get(c, 0) - 1
print("Anagram" if all(v == 0 for v in counts.values()) else "Not Anagram")

p = input()
has_upper = False
has_lower = False
has_digit = False
has_special = False
for ch in p:
    if ch.isupper():
        has_upper = True
    elif ch.islower():
        has_lower = True
    elif ch.isdigit():
        has_digit = True
    else:
        has_special = True
score = (len(p) >= 8) + has_upper + has_lower + has_digit + has_special
if score == 5:
    print("Strong")
elif score >= 3:
    print("Moderate")
else:
    print("Weak")

