s = input()
k = int(input())
out = []
for ch in s:
    if "A" <= ch <= "Z":
        base = ord("A")
        out.append(chr(base + (ord(ch) - base + k) % 26))
    elif "a" <= ch <= "z":
        base = ord("a")
        out.append(chr(base + (ord(ch) - base + k) % 26))
    else:
        out.append(ch)
print("".join(out))

s = input()
last_seen = {}
left = 0
best = 0
for right, ch in enumerate(s):
    if ch in last_seen and last_seen[ch] >= left:
        left = last_seen[ch] + 1
    last_seen[ch] = right
    window_len = right - left + 1
    if window_len > best:
        best = window_len
print(best)

s = input()
pairs = {")": "(", "]": "[", "}": "{"}
stack = []
valid = True
for ch in s:
    if ch in "([{":
        stack.append(ch)
    elif ch in pairs:
        if not stack or stack.pop() != pairs[ch]:
            valid = False
            break
print("Balanced" if valid and not stack else "Not Balanced")
